class Solution {
    static class TreeNode {
        int val;
        TreeNode left, right;
        TreeNode(int val) { this.val = val; }
    }
    static class Entry {
        TreeNode node;
        int depth;
        Entry(TreeNode node, int depth) { this.node = node; this.depth = depth; }
    }

    public int maxDepth(TreeNode root) {
        if (root == null) return 0;
        Deque<Entry> stack = new ArrayDeque<>();
        stack.push(new Entry(root, 1));
        int max = 0;
        while (!stack.isEmpty()) {
            Entry current = stack.pop();
            max = Math.max(max, current.depth);
            if (current.node.left != null)
                stack.push(new Entry(current.node.left, current.depth + 1));
            if (current.node.right != null)
                stack.push(new Entry(current.node.right, current.depth + 1));
        }
        return max;
    }
}

