class Solution {
    public int[] topKFrequent(int[] nums, int k) {
        Map<Integer, Integer> frequency = new HashMap<>();
        for (int x : nums) frequency.merge(x, 1, Integer::sum);
        PriorityQueue<Integer> heap = new PriorityQueue<>((a, b) -> {
            int byFrequency = Integer.compare(frequency.get(a), frequency.get(b));
            return byFrequency != 0 ? byFrequency : Integer.compare(b, a);
        });
        for (int x : frequency.keySet()) {
            heap.offer(x);
            if (heap.size() > k) heap.poll();
        }
        List<Integer> chosen = new ArrayList<>(heap);
        chosen.sort((a, b) -> {
            int byFrequency = Integer.compare(frequency.get(b), frequency.get(a));
            return byFrequency != 0 ? byFrequency : Integer.compare(a, b);
        });
        int[] result = new int[k];
        for (int i = 0; i < k; i++) result[i] = chosen.get(i);
        return result;
    }
}

