class Solution {
    public int numIslands(char[][] grid) {
        int rows = grid.length, cols = grid[0].length;
        int islands = 0;
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};
        Queue<Integer> queue = new ArrayDeque<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '1') continue;
                islands++;
                grid[r][c] = '0';
                queue.offer(r * cols + c);
                while (!queue.isEmpty()) {
                    int cell = queue.poll();
                    int row = cell / cols, col = cell % cols;
                    for (int k = 0; k < 4; k++) {
                        int nr = row + dr[k], nc = col + dc[k];
                        if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || grid[nr][nc] != '1') continue;
                        grid[nr][nc] = '0';
                        queue.offer(nr * cols + nc);
                    }
                }
            }
        }
        return islands;
    }
}

class Solution {
    public int[] findRedundantConnection(int[][] edges){
        int n=edges.length;int[] p=new int[n+1],rank=new int[n+1];
        for(int i=1;i<=n;i++)p[i]=i;
        for(int[] e:edges){
            int a=find(p,e[0]),b=find(p,e[1]);
            if(a==b)return e;
            if(rank[a]<rank[b])p[a]=b;
            else if(rank[a]>rank[b])p[b]=a;
            else{p[b]=a;rank[a]++;}
        }
        return new int[0];
    }
    private int find(int[] p,int x){if(p[x]!=x)p[x]=find(p,p[x]);return p[x];}
}

