class Solution {
    public double findMedianSortedArrays(int[] a,int[] b){
        if(a.length>b.length)return findMedianSortedArrays(b,a);
        int m=a.length,n=b.length,left=(m+n+1)/2,lo=0,hi=m;
        while(lo<=hi){
            int i=lo+(hi-lo)/2,j=left-i;
            int al=i==0?Integer.MIN_VALUE:a[i-1];
            int ar=i==m?Integer.MAX_VALUE:a[i];
            int bl=j==0?Integer.MIN_VALUE:b[j-1];
            int br=j==n?Integer.MAX_VALUE:b[j];
            if(al<=br&&bl<=ar){
                int maxLeft=Math.max(al,bl);
                if(((m+n)&1)==1)return maxLeft;
                return ((long)maxLeft+Math.min(ar,br))/2.0;
            }
            if(al>br)hi=i-1;
            else lo=i+1;
        }
        throw new IllegalArgumentException("Unsorted input");
    }
}

