class SortAlgorithms {
    static void mergeSort(int[] a) { sort(a,new int[a.length],0,a.length); }
    private static void sort(int[] a,int[] tmp,int lo,int hi) {
        if(hi-lo<=1)return;
        int mid=lo+(hi-lo)/2;
        sort(a,tmp,lo,mid);sort(a,tmp,mid,hi);
        int i=lo,j=mid,k=lo;
        while(i<mid&&j<hi)tmp[k++]=a[i]<=a[j]?a[i++]:a[j++];
        while(i<mid)tmp[k++]=a[i++];
        while(j<hi)tmp[k++]=a[j++];
        for(int x=lo;x<hi;x++)a[x]=tmp[x];
    }
}

class SortAlgorithms {
    static void quickSort(int[] a) { sort(a,0,a.length-1); }
    private static void sort(int[] a,int lo,int hi) {
        if(lo>=hi)return;
        int pivot=a[hi],boundary=lo;
        for(int i=lo;i<hi;i++)if(a[i]<=pivot){
            int t=a[i];a[i]=a[boundary];a[boundary]=t;boundary++;
        }
        a[hi]=a[boundary];a[boundary]=pivot;
        sort(a,lo,boundary-1);sort(a,boundary+1,hi);
    }
}

