class Solution {
    public int strStr(String haystack, String needle) {
        if (needle.isEmpty()) return 0;
        int[] pi=new int[needle.length()];
        for(int i=1,j=0;i<needle.length();i++){
            while(j>0&&needle.charAt(i)!=needle.charAt(j))j=pi[j-1];
            if(needle.charAt(i)==needle.charAt(j))j++;
            pi[i]=j;
        }
        for(int i=0,j=0;i<haystack.length();i++){
            while(j>0&&haystack.charAt(i)!=needle.charAt(j))j=pi[j-1];
            if(haystack.charAt(i)==needle.charAt(j))j++;
            if(j==needle.length())return i-j+1;
        }
        return -1;
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

class Solution {
    public int[][] merge(int[][] intervals) {
        if (intervals.length == 0) return new int[0][2];
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));
        List<int[]> merged = new ArrayList<>();
        int start = intervals[0][0];
        int end = intervals[0][1];
        for (int i = 1; i < intervals.length; i++) {
            if (intervals[i][0] <= end) {
                end = Math.max(end, intervals[i][1]);
            } else {
                merged.add(new int[] {start, end});
                start = intervals[i][0];
                end = intervals[i][1];
            }
        }
        merged.add(new int[] {start, end});
        return merged.toArray(new int[merged.size()][]);
    }
}

import java.util.*;
class Solution {
    public int eraseOverlapIntervals(int[][] intervals) {
        Arrays.sort(intervals,(a,b)->Integer.compare(a[1],b[1]));
        int keep=0, end=Integer.MIN_VALUE;
        for(int[] in:intervals)if(in[0]>=end){keep++;end=in[1];}
        return intervals.length-keep;
    }
}

import java.util.*;
class Solution {
    public int orangesRotting(int[][] grid){
        Deque<int[]> q=new ArrayDeque<>();
        int fresh=0,mins=0;
        for(int r=0;r<grid.length;r++)for(int c=0;c<grid[0].length;c++){
            if(grid[r][c]==1)fresh++;
            if(grid[r][c]==2)q.offer(new int[]{r,c});
        }
        int[][] dirs={{1,0},{-1,0},{0,1},{0,-1}};
        while(!q.isEmpty()&&fresh>0){
            int size=q.size();
            for(int i=0;i<size;i++){
                int[] cur=q.poll();
                for(int[] d:dirs){
                    int r=cur[0]+d[0],c=cur[1]+d[1];
                    if(r>=0&&c>=0&&r<grid.length&&c<grid[0].length&&grid[r][c]==1){
                        grid[r][c]=2;fresh--;q.offer(new int[]{r,c});
                    }
                }
            }
            mins++;
        }
        return fresh==0?mins:-1;
    }
}

import java.util.ArrayDeque;
import java.util.Queue;

class Solution {
    public int numIslands(char[][] grid) {
        int rows = grid.length, cols = grid[0].length;
        int islands = 0;
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};
        Queue<Integer> queue = new ArrayDeque<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '1') continue;
                islands++;
                grid[r][c] = '0';
                queue.offer(r * cols + c);
                while (!queue.isEmpty()) {
                    int cell = queue.poll();
                    int row = cell / cols, col = cell % cols;
                    for (int k = 0; k < 4; k++) {
                        int nr = row + dr[k], nc = col + dc[k];
                        if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || grid[nr][nc] != '1') continue;
                        grid[nr][nc] = '0';
                        queue.offer(nr * cols + nc);
                    }
                }
            }
        }
        return islands;
    }
}

import java.util.*;
class Solution {
    public int[] findOrder(int n,int[][] prerequisites){
        List<List<Integer>> g=new ArrayList<>();
        for(int i=0;i<n;i++)g.add(new ArrayList<>());
        int[] indeg=new int[n];
        for(int[] e:prerequisites){g.get(e[1]).add(e[0]);indeg[e[0]]++;}
        Deque<Integer> q=new ArrayDeque<>();
        for(int i=0;i<n;i++)if(indeg[i]==0)q.offer(i);
        int[] order=new int[n];int k=0;
        while(!q.isEmpty()){
            int x=q.poll();order[k++]=x;
            for(int y:g.get(x))if(--indeg[y]==0)q.offer(y);
        }
        return k==n?order:new int[0];
    }
}

class Solution {
    public int[] findRedundantConnection(int[][] edges){
        int n=edges.length;int[] p=new int[n+1],rank=new int[n+1];
        for(int i=1;i<=n;i++)p[i]=i;
        for(int[] e:edges){
            int a=find(p,e[0]),b=find(p,e[1]);
            if(a==b)return e;
            if(rank[a]<rank[b])p[a]=b;
            else if(rank[a]>rank[b])p[b]=a;
            else{p[b]=a;rank[a]++;}
        }
        return new int[0];
    }
    private int find(int[] p,int x){if(p[x]!=x)p[x]=find(p,p[x]);return p[x];}
}

import java.util.*;
class Solution {
    public int networkDelayTime(int[][] times,int n,int k){
        List<List<int[]>> g=new ArrayList<>();
        for(int i=0;i<=n;i++)g.add(new ArrayList<>());
        for(int[] e:times)g.get(e[0]).add(new int[]{e[1],e[2]});
        int[] dist=new int[n+1];Arrays.fill(dist,Integer.MAX_VALUE);dist[k]=0;
        PriorityQueue<int[]> pq=new PriorityQueue<>((a,b)->Integer.compare(a[0],b[0]));
        pq.offer(new int[]{0,k});
        while(!pq.isEmpty()){
            int[] cur=pq.poll();int d=cur[0],u=cur[1];
            if(d!=dist[u])continue;
            for(int[] e:g.get(u)){
                int v=e[0],nd=d+e[1];
                if(nd<dist[v]){dist[v]=nd;pq.offer(new int[]{nd,v});}
            }
        }
        int best=0;
        for(int i=1;i<=n;i++){
            if(dist[i]==Integer.MAX_VALUE)return -1;
            best=Math.max(best,dist[i]);
        }
        return best;
    }
}

import java.util.*;
class Solution {
    public int findCheapestPrice(int n,int[][] flights,int src,int dst,int k){
        int INF=1_000_000_000;
        int[] dist=new int[n];Arrays.fill(dist,INF);dist[src]=0;
        for(int edges=0;edges<=k;edges++){
            int[] next=dist.clone();
            for(int[] f:flights)if(dist[f[0]]!=INF)
                next[f[1]]=Math.min(next[f[1]],dist[f[0]]+f[2]);
            dist=next;
        }
        return dist[dst]==INF?-1:dist[dst];
    }
}

import java.util.*;
class KruskalMST {
    static int minCost(int n,int[][] edges) {
        Arrays.sort(edges,(a,b)->Integer.compare(a[2],b[2]));
        int[] parent=new int[n],size=new int[n];
        for(int i=0;i<n;i++){parent[i]=i;size[i]=1;}
        int cost=0,used=0;
        for(int[] e:edges) {
            int a=find(parent,e[0]),b=find(parent,e[1]);
            if(a==b)continue;
            if(size[a]<size[b]){int t=a;a=b;b=t;}
            parent[b]=a;size[a]+=size[b];
            cost+=e[2];used++;
            if(used==n-1)return cost;
        }
        return n<=1?0:-1;
    }
    private static int find(int[] p,int x) {
        if(p[x]!=x)p[x]=find(p,p[x]);
        return p[x];
    }
}

import java.util.*;
class MemoExample {
    static long fibonacci(int n) {
        long[] memo=new long[n+1];
        Arrays.fill(memo,-1L);
        return solve(n,memo);
    }
    private static long solve(int n,long[] memo){
        if(n<=1)return n;
        if(memo[n]!=-1)return memo[n];
        return memo[n]=solve(n-1,memo)+solve(n-2,memo);
    }
}

class Solution {
    public int rob(int[] nums){
        int prev2=0,prev1=0;
        for(int value:nums){
            int best=Math.max(prev1,prev2+value);
            prev2=prev1;prev1=best;
        }
        return prev1;
    }
}

class Solution {
    public int longestCommonSubsequence(String a,String b){
        int[] dp=new int[b.length()+1];
        for(int i=1;i<=a.length();i++){
            int diagonal=0;
            for(int j=1;j<=b.length();j++){
                int above=dp[j];
                if(a.charAt(i-1)==b.charAt(j-1))dp[j]=diagonal+1;
                else dp[j]=Math.max(dp[j],dp[j-1]);
                diagonal=above;
            }
        }
        return dp[b.length()];
    }
}

class Solution {
    public boolean canPartition(int[] nums){
        int sum=0;for(int x:nums)sum+=x;
        if((sum&1)!=0)return false;
        int target=sum/2;boolean[] dp=new boolean[target+1];dp[0]=true;
        for(int x:nums)for(int s=target;s>=x;s--)dp[s]|=dp[s-x];
        return dp[target];
    }
}

class Solution {
    public int minDistance(String a,String b){
        int[] dp=new int[b.length()+1];
        for(int j=0;j<=b.length();j++)dp[j]=j;
        for(int i=1;i<=a.length();i++){
            int diagonal=dp[0];dp[0]=i;
            for(int j=1;j<=b.length();j++){
                int above=dp[j];
                if(a.charAt(i-1)==b.charAt(j-1))dp[j]=diagonal;
                else dp[j]=1+Math.min(diagonal,Math.min(above,dp[j-1]));
                diagonal=above;
            }
        }
        return dp[b.length()];
    }
}

