class NumberTheory {
    static int gcd(int a,int b) {
        a=Math.abs(a);b=Math.abs(b);
        while(b!=0){int remainder=a%b;a=b;b=remainder;}
        return a;
    }
}

import java.util.*;
class NumberTheory {
    static List<Integer> primesUpTo(int n) {
        boolean[] composite=new boolean[n+1];
        for(int p=2;(long)p*p<=n;p++)if(!composite[p])
            for(int multiple=p*p;multiple<=n;multiple+=p)composite[multiple]=true;
        List<Integer> primes=new ArrayList<>();
        for(int i=2;i<=n;i++)if(!composite[i])primes.add(i);
        return primes;
    }
}

class NumArray {
    private final int[] bit,values;
    public NumArray(int[] nums){
        values=nums.clone();bit=new int[nums.length+1];
        for(int i=0;i<nums.length;i++)add(i+1,nums[i]);
    }
    private void add(int i,int delta){
        for(;i<bit.length;i+=i&-i)bit[i]+=delta;
    }
    private int prefix(int end){
        int sum=0;
        for(int i=end;i>0;i-=i&-i)sum+=bit[i];
        return sum;
    }
    public void update(int index,int val){
        int delta=val-values[index];values[index]=val;add(index+1,delta);
    }
    public int sumRange(int left,int right){return prefix(right+1)-prefix(left);}
}

class MyCalendarThree {
    private static class Node {Node left,right;int add,best;}
    private final Node root=new Node();
    public int book(int start,int end){
        update(root,0,1_000_000_000,start,end-1);
        return root.best;
    }
    private void update(Node node,int lo,int hi,int ql,int qr){
        if(ql<=lo&&hi<=qr){node.add++;node.best++;return;}
        int mid=lo+(hi-lo)/2;
        if(ql<=mid){
            if(node.left==null)node.left=new Node();
            update(node.left,lo,mid,ql,qr);
        }
        if(qr>mid){
            if(node.right==null)node.right=new Node();
            update(node.right,mid+1,hi,ql,qr);
        }
        int a=node.left==null?0:node.left.best;
        int b=node.right==null?0:node.right.best;
        node.best=node.add+Math.max(a,b);
    }
}

import java.util.*;
class LRUCache extends LinkedHashMap<Integer,Integer> {
    private final int capacity;
    public LRUCache(int capacity){super(capacity,0.75f,true);this.capacity=capacity;}
    public int get(int key){return super.getOrDefault(key,-1);}
    public void put(int key,int value){super.put(key,value);}
    @Override protected boolean removeEldestEntry(Map.Entry<Integer,Integer> eldest){
        return size()>capacity;
    }
}

import java.util.*;
class MedianFinder {
    private final PriorityQueue<Integer> low=new PriorityQueue<>(Comparator.reverseOrder());
    private final PriorityQueue<Integer> high=new PriorityQueue<>();
    public void addNum(int num){
        low.offer(num);high.offer(low.poll());
        if(high.size()>low.size())low.offer(high.poll());
    }
    public double findMedian(){
        if(low.size()>high.size())return low.peek();
        return ((long)low.peek()+high.peek())/2.0;
    }
}

class Solution {
    public double findMedianSortedArrays(int[] a,int[] b){
        if(a.length>b.length)return findMedianSortedArrays(b,a);
        int m=a.length,n=b.length,left=(m+n+1)/2,lo=0,hi=m;
        while(lo<=hi){
            int i=lo+(hi-lo)/2,j=left-i;
            int al=i==0?Integer.MIN_VALUE:a[i-1];
            int ar=i==m?Integer.MAX_VALUE:a[i];
            int bl=j==0?Integer.MIN_VALUE:b[j-1];
            int br=j==n?Integer.MAX_VALUE:b[j];
            if(al<=br&&bl<=ar){
                int maxLeft=Math.max(al,bl);
                if(((m+n)&1)==1)return maxLeft;
                return ((long)maxLeft+Math.min(ar,br))/2.0;
            }
            if(al>br)hi=i-1;
            else lo=i+1;
        }
        throw new IllegalArgumentException("Unsorted input");
    }
}

import java.util.*;
class SweepLineExample {
    static int maxSimultaneous(int[][] halfOpenIntervals) {
        TreeMap<Integer,Integer> change=new TreeMap<>();
        for(int[] interval:halfOpenIntervals) {
            change.merge(interval[0],1,Integer::sum);
            change.merge(interval[1],-1,Integer::sum);
        }
        int active=0,best=0;
        for(int delta:change.values()){
            active+=delta;best=Math.max(best,active);
        }
        return best;
    }
}

class Solution {
    public int maxCoins(int[] nums){
        int n=nums.length;int[] a=new int[n+2];
        a[0]=a[n+1]=1;
        for(int i=0;i<n;i++)a[i+1]=nums[i];
        int[][] dp=new int[n+2][n+2];
        for(int len=1;len<=n;len++){
            for(int left=1;left+len-1<=n;left++){
                int right=left+len-1;
                for(int last=left;last<=right;last++){
                    int gain=a[left-1]*a[last]*a[right+1];
                    dp[left][right]=Math.max(dp[left][right],dp[left][last-1]+gain+dp[last+1][right]);
                }
            }
        }
        return dp[1][n];
    }
}
